Set tItem = ##class(IHC.EAI.KPI.Schema.ComponentList).%New() Set tItem.Namespace = "All" Set tItem.ConfigName = "HddInterfaceWebserviceOperation" Set tItem.ListType = 1 Set tItem.KPI = "IHC.EAI.KPI.Controller.TransactionCount" Set tItem.BusinessType = "BusinessOperation" Set tStatus = tItem.%Save()
Set tItem = ##class(IHC.EAI.KPI.Schema.ComponentList).%New() Set tItem.Namespace = "All" Set tItem.ConfigName = "Out-APE-Alert-REST" Set tItem.ListType = 1 Set tItem.KPI = "IHC.EAI.KPI.Controller.TransactionCount" Set tItem.BusinessType = "BusinessOperation" Set tStatus = tItem.%Save()
Set tItem = ##class(IHC.EAI.KPI.Schema.ComponentList).%New() Set tItem.Namespace = "All" Set tItem.ConfigName = "PagerAlert" Set tItem.ListType = 1 Set tItem.KPI = "IHC.EAI.KPI.Controller.TransactionCount" Set tItem.BusinessType = "BusinessOperation" Set tStatus = tItem.%Save()
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus
